    /// <summary>
    /// Informs the server about the number of pending bot updates if they haven't been processed for a long time; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetBotUpdatesStatusAsync(int pendingUpdateCount = default, string errorMessage = default)
    {

           using var activity =  StartCallActivity("SetBotUpdatesStatusAsync", typeof(SetBotUpdatesStatus).FullName ?? "SetBotUpdatesStatusAsync");

           try
           {
             return client.SetBotUpdatesStatusAsync(pendingUpdateCount, errorMessage);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
